import { Suspense } from 'react'
import { getProjectDetails, getProjectSlugs, getProjectTitle } from '@/lib/data'

// Prerender the projects the dashboard links to. Their cached title resolves
// at build time and joins the static shell, so it is prefetched by the Link
// and appears instantly on navigation.
export async function generateStaticParams() {
  const slugs = await getProjectSlugs()
  return slugs.map((slug) => ({ slug }))
}

export default function ProjectPage({ params }: PageProps<'/projects/[slug]'>) {
  // NOTE: do not `await params` here. Awaiting at the top would block the whole
  // static shell. Pass the promise down and await it inside each Suspense
  // boundary so the shell (and the prefetched title) stays reusable.
  return (
    <main>
      <Suspense fallback={<h1>Loading project...</h1>}>
        <ProjectTitle params={params} />
      </Suspense>
      <Suspense fallback={<ProjectDetailsSkeleton />}>
        <ProjectDetails params={params} />
      </Suspense>
    </main>
  )
}

async function ProjectTitle({
  params,
}: Pick<PageProps<'/projects/[slug]'>, 'params'>) {
  const { slug } = await params
  // getProjectTitle is cached (`'use cache'`), so for the slugs listed in
  // generateStaticParams this resolves into the prerendered shell and is
  // prefetched — the title shows up instantly on navigation.
  const title = await getProjectTitle(slug)
  return <h1>{title}</h1>
}

async function ProjectDetails({
  params,
}: Pick<PageProps<'/projects/[slug]'>, 'params'>) {
  const { slug } = await params
  // getProjectDetails is intentionally uncached, so this subtree is a dynamic
  // hole: it is NOT part of the prefetched shell and streams in on navigation.
  const details = await getProjectDetails(slug)
  return (
    <>
      <p>{details.description}</p>
      <h2>Recent activity</h2>
      <ul>
        {details.activity.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </>
  )
}

function ProjectDetailsSkeleton() {
  return (
    <>
      <p>Loading details…</p>
      <h2>Recent activity</h2>
      <ul>
        <li>Loading…</li>
      </ul>
    </>
  )
}
